const records = $input.all().map(item => item.json);

// 1. Eksik veya geçersiz audit kayıtlarını çıkar
const validRecords = records.filter(r =>
  r.pipeline_id &&
  r.commit_id &&
  r.spec_path &&
  r.document_type &&
  r.kb_url &&
  r.target_version &&
  r.status
);

// 2. Her doküman + commit + versiyon için
// en güncel audit kaydını belirle
const latestByDocument = new Map();

for (const record of validRecords) {
  const key = JSON.stringify([
    record.pipeline_id,
    record.commit_id,
    record.spec_path,
    record.document_type,
    record.kb_url,
    record.target_version
  ]);

  const existing = latestByDocument.get(key);

  const recordTime = Date.parse(
    record.processed_at ||
    record.updatedAt ||
    record.createdAt ||
    ''
  ) || 0;

  const existingTime = existing
    ? (Date.parse(
        existing.processed_at ||
        existing.updatedAt ||
        existing.createdAt ||
        ''
      ) || 0)
    : -1;

  if (
    !existing ||
    recordTime > existingTime ||
    (recordTime === existingTime &&
      Number(record.id || 0) > Number(existing.id || 0))
  ) {
    latestByDocument.set(key, record);
  }
}

// 3. Sadece recovery gerektiren kayıtları seç
const recoveryStatuses = new Set([
  'FAILED',
  'TIMEOUT',
  'PENDING_REVIEW'
]);

const candidates = [...latestByDocument.values()]
  .filter(r =>
    recoveryStatuses.has(
      String(r.status).trim().toUpperCase()
    )
  );

// 4. Sonuçları sonraki node'lara aktar
return candidates.map(record => ({
  json: {
    ...record,
    original_status: String(record.status).toUpperCase(),
    recovery_action: 'VERIFY_KB',
    recovery_required: true
  }
}));

const response = $json;
const source = $('Loop Over Items').item.json;

const documents = Array.isArray(response.body)
  ? response.body
  : Array.isArray(response.body?.documents)
    ? response.body.documents
    : [];

// spec_name yerine gerçek dosya adını kullan
const expectedName = String(source.spec_path || '')
  .split('/')
  .pop()
  .replace(/\.md$/i, '')
  .trim()
  .toLowerCase();

const matches = documents.filter(doc =>
  String(doc.doc_name || '')
    .trim()
    .toLowerCase() === expectedName
);

let verificationStatus;

if (response.statusCode !== 200) {
  verificationStatus = 'CHECK_FAILED';
} else if (matches.length === 1) {
  verificationStatus = 'FOUND_IN_KB';
} else if (matches.length > 1) {
  verificationStatus = 'AMBIGUOUS';
} else {
  verificationStatus = 'NOT_FOUND';
}

const existingDoc =
  verificationStatus === 'FOUND_IN_KB'
    ? matches[0]
    : null;

return {
  json: {
    ...source,
    verification_status: verificationStatus,
    found_in_kb: Boolean(existingDoc),
    existing_doc_id: existingDoc?.doc_id || '',
    existing_doc_md5: existingDoc?.md5 || '',
    existing_doc_path: existingDoc?.path || '',
    matching_documents: matches.length,
    http_status: response.statusCode
  }
};

const response = $json;
const source = $('Verify KB Document').item.json;

const jobs = Array.isArray(response.body)
  ? response.body
  : Array.isArray(response.body?.jobs)
    ? response.body.jobs
    : [];

const expectedFile = source.spec_path
  .split('/')
  .pop()
  .toLowerCase();

const matchingJobs = jobs.filter(job =>
  String(job.file_name || '').toLowerCase() === expectedFile &&
  String(job.version || '') === String(source.target_version)
);

const completedJobs = matchingJobs.filter(job =>
  String(job.status || '').toLowerCase() === 'done' &&
  Boolean(job.doc_id)
);

const activeJobs = matchingJobs.filter(job =>
  ['pending', 'queued', 'running', 'processing', 'in_progress']
    .includes(String(job.status || '').toLowerCase())
);

let recoveryDecision = 'MANUAL_REVIEW';
let recoveredDocId = '';

if (response.statusCode !== 200) {
  recoveryDecision = 'JOB_CHECK_FAILED';
} else if (activeJobs.length > 0) {
  recoveryDecision = 'WAIT_FOR_JOB';
} else if (completedJobs.length > 0) {
  const ids = [...new Set(completedJobs.map(job => job.doc_id))];

  if (ids.length === 1) {
    recoveryDecision = 'VERIFY_COMPLETED_DOC';
    recoveredDocId = ids[0];
  } else {
    recoveryDecision = 'MANUAL_REVIEW';
  }
} else if (matchingJobs.length === 0) {
  recoveryDecision = 'JOB_NOT_FOUND';
} else {
  recoveryDecision = 'MANUAL_REVIEW';
}

return {
  json: {
    ...source,
    matching_job_count: matchingJobs.length,
    completed_job_count: completedJobs.length,
    active_job_count: activeJobs.length,
    recovered_doc_id: recoveredDocId,
    recovery_decision: recoveryDecision
  }
};

const crypto = require('crypto');

const response = $json;
const githubFile = response.body ?? response;

const source = $('Verify KB Document').item.json;

if (githubFile.encoding !== 'base64' || !githubFile.content) {
  throw new Error('GitHub dosya içeriği Base64 formatında değil.');
}

// GitHub Base64 içeriğini gerçek byte'lara dönüştür
const fileBuffer = Buffer.from(
  githubFile.content.replace(/\s/g, ''),
  'base64'
);

// MD5 hesapla
const sourceMd5 = crypto
  .createHash('md5')
  .update(fileBuffer)
  .digest('hex');

const kbMd5 = String(source.existing_doc_md5 || '')
  .toLowerCase();

const md5Matches = sourceMd5 === kbMd5;

return {
  json: {
    ...source,
    github_blob_sha: githubFile.sha,
    github_file_size: fileBuffer.length,
    source_md5: sourceMd5,
    kb_md5: kbMd5,
    md5_matches: md5Matches,
    recovery_decision: md5Matches
      ? 'ALREADY_INDEXED'
      : 'CONTENT_MISMATCH'
  }
};

const response = $json;
const source = $('Evaluate Recovery Jobs').item.json;

const documents = Array.isArray(response.body)
  ? response.body
  : [];

const expectedName = String(source.spec_path || '')
  .split('/')
  .pop()
  .replace(/\.md$/i, '')
  .toLowerCase();

const matches = documents.filter(doc =>
  String(doc.doc_name || '').toLowerCase() === expectedName &&
  String(doc.doc_id || doc.id || '') ===
    String(source.recovered_doc_id || '')
);

const verified =
  response.statusCode === 200 &&
  matches.length === 1 &&
  Boolean(matches[0]?.md5);

const doc = verified ? matches[0] : null;

return {
  json: {
    ...source,
    verification_status: verified
      ? 'FOUND_IN_KB'
      : 'NOT_VERIFIED',
    found_in_kb: verified,
    existing_doc_id: doc?.doc_id || '',
    existing_doc_md5: doc?.md5 || '',
    existing_doc_path: doc?.path || '',
    matching_documents: matches.length,
    http_status: response.statusCode
  }
};

const crypto = require('crypto');

const response = $json;
const githubFile = response.body ?? response;

const source = $('Verify Rechecked Document').item.json;

if (githubFile.encoding !== 'base64' || !githubFile.content) {
  throw new Error('GitHub dosya içeriği Base64 formatında değil.');
}

// GitHub Base64 içeriğini gerçek byte'lara dönüştür
const fileBuffer = Buffer.from(
  githubFile.content.replace(/\s/g, ''),
  'base64'
);

// MD5 hesapla
const sourceMd5 = crypto
  .createHash('md5')
  .update(fileBuffer)
  .digest('hex');

const kbMd5 = String(source.existing_doc_md5 || '')
  .toLowerCase();

const md5Matches = sourceMd5 === kbMd5;

return {
  json: {
    ...source,
    github_blob_sha: githubFile.sha,
    github_file_size: fileBuffer.length,
    source_md5: sourceMd5,
    kb_md5: kbMd5,
    md5_matches: md5Matches,
    recovery_decision: md5Matches
      ? 'ALREADY_INDEXED'
      : 'CONTENT_MISMATCH'
  }
};

const record = $json;

const requiredFields = [
  'pipeline_id',
  'commit_id',
  'spec_path',
  'spec_name',
  'document_type',
  'kb_url',
  'target_version',
  'status'
];

const missingFields = requiredFields.filter(field =>
  record[field] === undefined ||
  record[field] === null ||
  String(record[field]).trim() === ''
);

if (missingFields.length > 0) {
  throw new Error(
    'Missing required audit fields: ' +
    missingFields.join(', ')
  );
}

// Yalnızca spec_refkb_audit tablosundaki sütunları döndür
return {
  json: {
    pipeline_id: record.pipeline_id,
    commit_id: record.commit_id,
    spec_path: record.spec_path,
    spec_name: record.spec_name,
    document_type: record.document_type,
    kb_url: record.kb_url,
    target_version: record.target_version,
    doc_id: String(record.doc_id ?? '').replace(/^['"]+|['"]+$/g, '').trim(),
    status: String(record.status).toUpperCase(),
    error_message: record.error_message || '',
    processed_at: new Date().toISOString()
  }
};

const history = $input.all()
  .map(item => item.json)
  .filter(row => row && row.spec_path && row.status);

const runIndex = $runIndex;

const newRecord = $('Normalize Recovery Audit')
  .all(0, runIndex)[0]?.json;

if (!newRecord) {
  throw new Error(
    `New recovery audit record missing at run ${runIndex}`
  );
}

const norm = value =>
  String(value ?? '')
    .replace(/^['"]+|['"]+$/g, '')
    .trim();

const matchingHistory = history.filter(row =>
  norm(row.pipeline_id) === norm(newRecord.pipeline_id) &&
  norm(row.commit_id) === norm(newRecord.commit_id) &&
  norm(row.spec_path) === norm(newRecord.spec_path) &&
  norm(row.target_version) === norm(newRecord.target_version)
);

const duplicate = matchingHistory.find(row =>
  norm(row.status).toUpperCase() ===
    norm(newRecord.status).toUpperCase() &&
  norm(row.doc_id) === norm(newRecord.doc_id) &&
  norm(row.error_message) === norm(newRecord.error_message)
);

return [{
  json: {
    ...newRecord,
    should_save: !duplicate,
    audit_action: duplicate
      ? 'SKIP_DUPLICATE'
      : 'INSERT',
    previous_audit_id: duplicate?.id ?? null
  }
}];

const rows = $input.all()
  .map(item => item.json)
  .filter(r =>
    r.pipeline_id &&
    r.commit_id &&
    r.spec_path &&
    r.target_version
  );

const groups = new Map();

for (const row of rows) {
  const key = JSON.stringify([
    row.pipeline_id,
    row.commit_id,
    row.spec_path,
    row.target_version
  ]);

  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(row);
}

const duplicates = [];

for (const [key, records] of groups.entries()) {
  records.sort((a, b) =>
    Number(a.id || 0) - Number(b.id || 0)
  );

  for (let i = 1; i < records.length; i++) {
    const previous = records[i - 1];
    const current = records[i];

    const same =
      String(previous.status || '') === String(current.status || '') &&
      String(previous.doc_id || '') === String(current.doc_id || '') &&
      String(previous.error_message || '') ===
        String(current.error_message || '');

    if (same) {
      duplicates.push({
        spec_path: current.spec_path,
        previous_id: previous.id,
        duplicate_id: current.id,
        status: current.status
      });
    }
  }
}

return [{
  json: {
    total_rows: $input.all().length,
    valid_rows: rows.length,
    duplicate_count: duplicates.length,
    duplicates
  }
}];

const r = $json;

const normalize = v => String(v ?? '').trim();

const isNotFound =
  r.verification_status === 'NOT_FOUND' &&
  r.found_in_kb === false &&
  Number(r.matching_documents ?? 0) === 0;

const noMatchingJobs =
  Number(r.matching_job_count ?? 0) === 0 &&
  Number(r.active_job_count ?? 0) === 0 &&
  Number(r.completed_job_count ?? 0) === 0;

const validSourceMetadata =
  /(?:^|\/)(BRS|SRS|SDS)\/Reference\/[^/]+\.md$/i.test(
    normalize(r.spec_path)
  ) &&
  Boolean(normalize(r.spec_name)) &&
  ['BRS', 'SRS', 'SDS'].includes(
    normalize(r.document_type).toUpperCase()
  ) &&
  normalize(r.target_version) === 'v2.13' &&
  Boolean(normalize(r.commit_id)) &&
  r.pipeline_id === 'dnext-product-docs-reference';
const eligible =
  r.recovery_decision === 'JOB_NOT_FOUND' &&
  Number(r.http_status) === 200 &&
  isNotFound &&
  noMatchingJobs &&
  validSourceMetadata;

return {
  json: {
    ...r,
    retry_candidate: eligible,
    retry_approved: false,
    retry_decision: eligible
      ? 'PRECHECK_REQUIRED'
      : 'MANUAL_REVIEW',
    retry_reason: eligible
      ? 'No matching KB document or job; final checks required'
      : 'Recovery conditions not satisfied'
  }
};

const response = $json;
const file = response.body ?? response;

const source = $('Safe Retry Eligible?').item.json;

const errors = [];

if (response.statusCode !== undefined &&
    response.statusCode !== 200) {
  errors.push(`GitHub HTTP ${response.statusCode}`);
}

if (file.type && file.type !== 'file') {
  errors.push('GitHub response is not a file');
}

if (file.path !== source.spec_path) {
  errors.push('GitHub file path mismatch');
}

if (file.name !== source.spec_path.split('/').pop()) {
  errors.push('GitHub filename mismatch');
}

if (file.encoding !== 'base64') {
  errors.push('Expected base64 encoding');
}

if (!file.content || typeof file.content !== 'string') {
  errors.push('Missing GitHub file content');
}

if (!file.sha) {
  errors.push('Missing GitHub blob SHA');
}

return {
  json: {
    ...source,
    github_file_name: file.name ?? '',
    github_file_path: file.path ?? '',
    github_blob_sha: file.sha ?? '',
    github_file_size: file.size ?? 0,
    github_encoding: file.encoding ?? '',
    github_content_base64: file.content ?? '',
    source_valid: errors.length === 0,
    source_validation_errors: errors,
    retry_approved: false
  }
};

const response = $json;
const source = $('Validate Retry Source').item.json;

const httpOk = Number(response.statusCode) === 200;

const documents = Array.isArray(response.body)
  ? response.body
  : Array.isArray(response.body?.documents)
    ? response.body.documents
    : [];

const validBody =
  Array.isArray(response.body) ||
  Array.isArray(response.body?.documents);

const expectedName = String(source.spec_path || '')
  .split('/')
  .pop()
  .replace(/\.md$/i, '')
  .trim()
  .toLowerCase();

const matchingDocuments = documents.filter(doc => {
  const name = String(
    doc.doc_name ?? doc.name ?? doc.file_name ?? ''
  )
    .replace(/\.md$/i, '')
    .trim()
    .toLowerCase();

  const version = String(doc.version ?? '').trim();

  const path = String(doc.path ?? '');
  const versionMatches =
    version === source.target_version ||
    (!version && path.includes(
      '/' + source.target_version + '/'
    ));

  return name === expectedName && versionMatches;
});

let decision = 'MANUAL_REVIEW';
let reason = '';

if (!httpOk) {
  reason = `KB HTTP error: ${response.statusCode}`;
} else if (!validBody) {
  reason = 'Unexpected KB response format';
} else if (matchingDocuments.length > 0) {
  decision = 'SKIP_RETRY';
  reason = 'Document already exists in Reference KB';
} else if (documents.length > 0) {
  reason = 'KB returned documents requiring identity review';
} else {
  decision = 'RETRY_PRECHECK_PASSED';
  reason = 'No KB document found; proceed to retry preparation';
}

return {
  json: {
    ...source,
    final_kb_http_status: response.statusCode,
    final_kb_document_count: documents.length,
    final_kb_matching_count: matchingDocuments.length,
    final_kb_decision: decision,
    final_kb_reason: reason,
    retry_approved: false
  }
};

const r = $json;

const sourceValid = r.source_valid === true;
const retryCandidate = r.retry_candidate === true;

const kbClear =
  r.final_kb_http_status === 200 &&
  r.final_kb_decision === 'RETRY_PRECHECK_PASSED' &&
  r.final_kb_document_count === 0;

const jobsClear =
  r.recovery_decision === 'JOB_NOT_FOUND' &&
  r.http_status === 200 &&
  r.matching_job_count === 0 &&
  r.active_job_count === 0 &&
  r.completed_job_count === 0;

const sourceReady =
  typeof r.github_content_base64 === 'string' &&
  r.github_content_base64.length > 0 &&
  r.github_encoding === 'base64' &&
  r.github_file_path === r.spec_path;

const safeToRetry =
  sourceValid &&
  retryCandidate &&
  kbClear &&
  jobsClear &&
  sourceReady;

return {
  json: {
    ...r,
    retry_approved: safeToRetry,
    retry_decision: safeToRetry
      ? 'READY_FOR_UPLOAD'
      : 'MANUAL_REVIEW',
    retry_reason: safeToRetry
      ? 'All retry prechecks passed'
      : 'One or more retry prechecks failed'
  }
};

const r = $json;

if (r.retry_approved !== true) {
  throw new Error('Retry not approved');
}

if (r.source_valid !== true) {
  throw new Error('Source validation failed');
}

if (!r.github_content_base64) {
  throw new Error('GitHub content is missing');
}

const base64 = r.github_content_base64.replace(/\s/g, '');
const fileName = r.spec_path.split('/').pop();

if (!fileName.endsWith('.md')) {
  throw new Error('Expected Markdown file');
}

// Decode GitHub Base64 content
const fileBuffer = Buffer.from(base64, 'base64');

// Calculate source MD5
const crypto = require('crypto');
const githubSourceMd5 = crypto
  .createHash('md5')
  .update(fileBuffer)
  .digest('hex');

// Prepare n8n binary file
const binaryData = await this.helpers.prepareBinaryData(
  fileBuffer,
  fileName,
  'text/markdown'
);

// Remove large Base64 content from JSON
const {
  github_content_base64,
  ...metadata
} = r;

return {
  json: {
    ...metadata,
    github_source_md5: githubSourceMd5,
    retry_file_name: fileName,
    retry_file_size: fileBuffer.length,
    retry_file_ready: true
  },
  binary: {
    data: binaryData
  }
};

const response = $json;
const source = $('Prepare Retry File').item.json;
const upload = $('Retry Upload to KB').item.json;

const normalize = value =>
  String(value ?? '').trim();

const normalizeMd5 = value =>
  normalize(value).toLowerCase();

const documents = Array.isArray(response.body)
  ? response.body
  : [];

const uploadDocId = normalize(upload.body?.doc_id);

const matches = documents.filter(doc => {
  const docId = normalize(
    doc.doc_id ?? doc.id ?? doc.document_id
  );

  return uploadDocId !== '' && docId === uploadDocId;
});

const verifiedDoc = matches.length === 1
  ? matches[0]
  : null;

const githubMd5 = normalizeMd5(source.github_source_md5);
const kbMd5 = normalizeMd5(verifiedDoc?.md5);

const md5Valid =
  /^[a-f0-9]{32}$/.test(githubMd5) &&
  /^[a-f0-9]{32}$/.test(kbMd5);

const md5Matches =
  md5Valid && githubMd5 === kbMd5;

const httpOk = response.statusCode === 200;

const uploadOk =
  upload.statusCode === 200 &&
  upload.body?.status === 'indexed';

let status = 'PENDING_REVIEW';
let errorMessage = '';

if (!httpOk) {
  errorMessage = `Retry verification HTTP ${response.statusCode}`;
} else if (!Array.isArray(response.body)) {
  errorMessage = 'Unexpected verification response format';
} else if (!uploadOk) {
  errorMessage = 'Retry upload not confirmed as indexed';
} else if (!uploadDocId) {
  errorMessage = 'Retry upload returned no doc_id';
} else if (matches.length !== 1) {
  errorMessage = `Expected one matching KB document; found ${matches.length}`;
} else if (!md5Valid) {
  errorMessage = 'Missing or invalid GitHub/KB MD5';
} else if (!md5Matches) {
  errorMessage = `MD5 mismatch: GitHub=${githubMd5}, KB=${kbMd5}`;
} else {
  status = 'SUCCESS';
  errorMessage = '';
}

return {
  json: {
    pipeline_id: source.pipeline_id,
    commit_id: source.commit_id,
    spec_path: source.spec_path,
    spec_name: source.spec_name,
    document_type: source.document_type,
    kb_url: source.kb_url,
    target_version: source.target_version,

    doc_id: uploadDocId || null,
    status,
    error_message: errorMessage,
    processed_at: new Date().toISOString(),

    retry_upload_status: upload.body?.status ?? '',
    retry_job_id: upload.body?.job_id ?? '',

    github_source_md5: githubMd5,
    kb_document_md5: kbMd5,
    retry_md5_matches: md5Matches,

    retry_verified:
      httpOk &&
      uploadOk &&
      matches.length === 1 &&
      md5Matches,

    retry_verification_count: matches.length
  }
};
